      wal_file_path.c_str(), id(), (size_t)total_recovered_doc_count,
      (size_t)recovered_doc_count[0],  // INSERT
      (size_t)recovered_doc_count[1],  // UPSERT
      (size_t)recovered_doc_count[2],  // UPDATE
      (size_t)recovered_doc_count[3]   // DELETE
  );

  return Status::OK();
}

